    ignored_dir.join("__init__.py").ensure()

    # Mock pytest_ignore_collect to return True
    class MockHook:
        def pytest_ignore_collect(self, path, config):
            return True

    class MockPackage(Package):
        def gethookproxy(self, fspath):
            return MockHook()

    mock_package = MockPackage(fspath=package)
    result = mock_package._recurse(ignored_dir)
    assert result is None  # Should return None (fall through to return)

    # Test Path 3: Directory matches norecurse pattern
    test_dir = package.mkdir("test_dir")
    test_dir.join("__init__.py").ensure()

    # Set norecursepatterns to match test_dir
    class MockPackageWithPattern(Package):
        def __init__(self, fspath, parent=None, config=None, session=None, nodeid=None):
            super().__init__(fspath, parent=parent, config=config, session=session, nodeid=nodeid)
            self._norecursepatterns = ["test_dir"]

        def gethookproxy(self, fspath):
            return MockHook()

    mock_package_with_pattern = MockPackageWithPattern(fspath=package)
    result = mock_package_with_pattern._recurse(test_dir)
    assert result is False

    # Test Path 4: Directory matches second norecurse pattern
