    test_dir3 = package.mkdir("test_dir3")
    test_dir3.join("__init__.py").ensure()

    class MockPackageWithNoMatch(Package):
        def __init__(self, fspath, parent=None, config=None, session=None, nodeid=None):
            super().__init__(fspath, parent=parent, config=config, session=session, nodeid=nodeid)
            self._norecursepatterns = ["test_dir", "test_dir2"]

        def gethookproxy(self, fspath):
            return MockHook()

    mock_package_with_no_match = MockPackageWithNoMatch(fspath=package)
    result = mock_package_with_no_match._recurse(test_dir3)
    assert result is None  # Should return None (fall through to return True)

    # Test Path 6: No norecurse patterns and directory not ignored
    test_dir4 = package.mkdir("test_dir4")
    test_dir4.join("__init__.py").ensure()

    class MockPackageNoPatterns(Package):
        def __init__(self, fspath, parent=None, config=None, session=None, nodeid=None):
            super().__init__(fspath, parent=parent, config=config, session=session, nodeid=nodeid)
            self._norecursepatterns = []

        def gethookproxy(self, fspath):
            return MockHook()

    mock_package_no_patterns = MockPackageNoPatterns(fspath=package)
