    # Test Path 4: indirect is tuple/list with one arg in argnames, one not in argnames
    try:
        metafunc._resolve_arg_value_types(argnames, ['arg1', 'nonexistent'])
        assert False, "Should have raised ValueError"
    except Exception as e:
        assert "indirect fixture 'nonexistent' doesn't exist" in str(e)

    # Test Path 5: indirect is tuple/list with one arg not in argnames, loop exits after first iteration
    try:
