class SiteRegisterTests(TestCase):
    def setUp(self):
        self.site = admin.AdminSite()

    def test_register_single_model_abstract(self):
        """Test registering an abstract model raises ImproperlyConfigured."""
        class AbstractModel(models.Model):
            class Meta:
                abstract = True

        with self.assertRaises(ImproperlyConfigured):
            self.site.register(AbstractModel)

    def test_register_single_model_already_registered(self):
        """Test registering a model already registered raises AlreadyRegistered."""
        class TestModel(models.Model):
            pass

        self.site.register(TestModel)
        with self.assertRaises(AlreadyRegistered):
            self.site.register(TestModel)

    def test_register_single_model_not_swapped(self):
        """Test registering a non-abstract, non-registered model with no options."""
        class TestModel(models.Model):
            pass

        self.assertFalse(self.site.is_registered(TestModel))
        self.site.register(TestModel)
        self.assertTrue(self.site.is_registered(TestModel))

    def test_register_single_model_with_options(self):
        """Test registering a model with options creates a dynamic admin class."""
        class TestModel(models.Model):
            pass

        self.assertFalse(self.site.is_registered(TestModel))
        self.site.register(TestModel, list_display=['id'])
        self.assertTrue(self.site.is_registered(TestModel))
        admin_instance = self.site._registry[TestModel]
        self.assertEqual(admin_instance.list_display, ['id'])

    def test_register_multiple_models(self):
        """Test registering multiple models in a list."""
        class ModelA(models.Model):
            pass

        class ModelB(models.Model):
            pass

        self.assertFalse(self.site.is_registered(ModelA))
        self.assertFalse(self.site.is_registered(ModelB))
        self.site.register([ModelA, ModelB])
        self.assertTrue(self.site.is_registered(ModelA))
        self.assertTrue(self.site.is_registered(ModelB))

    def test_register_multiple_models_with_mixed_states(self):
        """Test registering multiple models with some already registered and some abstract."""
        class ModelA(models.Model):
            pass

        class ModelB(models.Model):
            class Meta:
                abstract = True

        class ModelC(models.Model):
            pass

        self.site.register(ModelA)
        with self.assertRaises(AlreadyRegistered):
            self.site.register([ModelA, ModelB, ModelC])

    def test_register_model_with_swapped(self):
        """Test that a swapped model is not registered."""
        class SwappedModel(models.Model):
            class Meta:
                app_label = 'test_app'
                swapped = True

        self.site.register(SwappedModel)
        self.assertFalse(self.site.is_registered(SwappedModel))

    def test_register_model_with_custom_admin_class(self):
        """Test registering with a custom admin class."""
        class CustomModelAdmin(admin.ModelAdmin):
            list_display = ['id']

        class TestModel(models.Model):
            pass

        self.site.register(TestModel, CustomModelAdmin)
        self.assertTrue(self.site.is_registered(TestModel))
        admin_instance = self.site._registry[TestModel]
        self.assertIsInstance(admin_instance, CustomModelAdmin)
        self.assertEqual(admin_instance.list_display, ['id'])

    def test_register_model_with_options_and_custom_admin_class(self):
        """Test registering with options and a custom admin class."""
        class CustomModelAdmin(admin.ModelAdmin):
            pass

        class TestModel(models.Model):
            pass

        self.site.register(TestModel, CustomModelAdmin, list_display=['id'])
        admin_instance = self.site._registry[TestModel]
        self.assertEqual(admin_instance.list_display, ['id'])

    def test_register_model_with_options_and_dynamic_class(self):
        """Test that dynamic admin class with options has correct module."""
        class TestModel(models.Model):
            pass

        self.site.register(TestModel, list_display=['id'])
        admin_instance = self.site._registry[TestModel]
        self.assertEqual(admin_instance.__module__, __name__)
