class MethodDecoratorDecTests(TestCase):
    def test_method_decorator_dec_function_case(self):
        """
        Test Path 1: When obj is not a class type, directly apply _multi_decorate.
        """
        def test_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        def test_func():
            return "test"

        # Apply method_decorator to a function directly
        result = method_decorator(test_decorator)(test_func)
        self.assertEqual(result(), "test")

    def test_method_decorator_dec_invalid_name_case(self):
        """
        Test Path 2: When name is not valid or method doesn't exist in class.
        """
        def test_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        msg = (
            "The keyword argument `name` must be the name of a method of the decorated class: <class 'Test'>. Got 'nonexistent' instead."
        )
        with self.assertRaisesMessage(ValueError, msg):
            @method_decorator(test_decorator, name="nonexistent")
            class Test:
                pass

    def test_method_decorator_dec_non_callable_attribute_case(self):
        """
        Test Path 3: When the attribute exists but is not callable.
        """
        def test_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        msg = (
            "Cannot decorate 'prop' as it isn't a callable attribute of <class 'Test'> (1)"
        )
        with self.assertRaisesMessage(TypeError, msg):
            @method_decorator(test_decorator, name="prop")
            class Test:
                prop = 1

    def test_method_decorator_dec_valid_method_case(self):
        """
        Test Path 4: When obj is a class, name is valid, method exists and is callable.
        """
        def test_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        @method_decorator(test_decorator, name="method")
        class Test:
            def method(self):
                return "original"

        instance = Test()
        self.assertEqual(instance.method(), "original_decorated")
        # Verify the method was replaced
        self.assertTrue(hasattr(Test, 'method'))
        self.assertTrue(callable(getattr(Test, 'method')))
