def test_pytest_collect_file_paths(pytester: Pytester) -> None:
    """Test all execution paths for pytest_collect_file function."""

    # Path 1: File is .py but not in initpath and doesn't match patterns
    # Create a .py file that doesn't match python_files patterns
    test_file = pytester.makepyfile(
        test_abc="def test_func(): pass"
    )
    # Override config to make python_files not match this file
    pytester.makeini(
        """
        [tool:pytest]
        python_files = test_*.py
        """
    )

    # Mock parent session and isinitpath to return False
    class MockParent:
        def __init__(self, config):
            self.config = config
            self.session = MockSession()

    class MockSession:
        def isinitpath(self, fspath):
            return False

    # Create config with python_files only matching test_*.py
    config = pytester.parseconfigure()

    # Mock gethookproxy to return a hook which returns None
    class MockHook:
        def pytest_pycollect_makemodule(self, fspath, parent):
            return None

    # Create mock hook proxy
    class MockHookProxy:
        def __init__(self, hook):
            self.hook = hook

        def pytest_pycollect_makemodule(self, fspath, parent):
            return self.hook.pytest_pycollect_makemodule(fspath, parent)

    # Mock session gethookproxy to return our mock hook
    class MockSessionWithHook:
        def __init__(self):
            self.hook = MockHook()

        def gethookproxy(self, fspath):
            return MockHookProxy(self.hook)

        def isinitpath(self, fspath):
            return False

    parent = MockParent(config)
    parent.session = MockSessionWithHook()

    # Test Path 1 - should return None
    result = pytest_collect_file(test_file.path, parent)
    assert result is None

    # Path 2: File is .py, not in initpath but matches patterns
    # Create a .py file that matches the python_files pattern
    test_file2 = pytester.makepyfile(
        test_abc="def test_func(): pass"
    )

    # Keep the same config that matches test_*.py
    config = pytester.parseconfigure()

    # Mock session to return False for isinitpath but make path_matches_patterns return True
    class MockSessionMatch:
        def gethookproxy(self, fspath):
            return MockHookProxy(MockHook())

        def isinitpath(self, fspath):
            return False

    parent2 = MockParent(config)
    parent2.session = MockSessionMatch()

    # Test Path 2 - should return module
    result2 = pytest_collect_file(test_file2.path, parent2)
    assert isinstance(result2, Module)

    # Path 3: File is .py and is in initpath
    # Create a .py file
    test_file3 = pytester.makepyfile(
        test_abc="def test_func(): pass"
    )

    # Mock session to return True for isinitpath
    class MockSessionInit:
        def gethookproxy(self, fspath):
            return MockHookProxy(MockHook())

        def isinitpath(self, fspath):
            return True

    parent3 = MockParent(config)
    parent3.session = MockSessionInit()

    # Test Path 3 - should return module
    result3 = pytest_collect_file(test_file3.path, parent3)
    assert isinstance(result3, Module)

    # Path 4: File is not .py
    # Create a non-.py file
    test_file4 = pytester.makefile(
        ".txt",
        test_text="some text"
    )

    # Mock parent session
    parent4 = MockParent(config)
    parent4.session = MockSessionInit()

    # Test Path 4 - should return None
    result4 = pytest_collect_file(test_file4.path, parent4)
    assert result4 is None
