def test_hasinit():
    class HasInit:
        def __init__(self):
            pass

    class HasInitOverride(HasInit):
        def __init__(self):
            super().__init__()

    class HasInitInherited(HasInitOverride):
        pass

    class NoInit:
        pass

    class HasInitNone:
        __init__ = None

    # Test case where __init__ exists and is not the default object.__init__
    assert hasinit(HasInit) is True
    assert hasinit(HasInitOverride) is True
    assert hasinit(HasInitInherited) is True

    # Test case where __init__ exists but is the default object.__init__
    assert hasinit(NoInit) is False

    # Test case where __init__ is explicitly set to None
    assert hasinit(HasInitNone) is False
```

