            pass

        class Model(models.Model):
            related1 = models.ForeignKey(RelatedModel1, on_delete=models.CASCADE)
            related2 = models.ForeignKey(RelatedModel2, on_delete=models.CASCADE)
            # Define a property with the same name as both related field accessors
            @property
            def related1(self):
                return "clashing property"

            @property
            def related2(self):
                return "clashing property"

        errors = checks.run_checks(app_configs=self.apps.get_app_configs())
