class ModelFormMetaclassTestCase(TestCase):
    def test_model_form_metaclass_with_base_formfield_callback(self):
        # Test Path 1: base_formfield_callback is set from a base class
        class BaseFormWithCallback(BaseModelForm):
            class Meta:
                formfield_callback = lambda f, **kwargs: f.formfield(**kwargs)

        class TestModelForm(BaseFormWithCallback):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

        # Verify that formfield_callback is properly inherited
        self.assertEqual(TestModelForm._meta.formfield_callback, BaseFormWithCallback.Meta.formfield_callback)

    def test_model_form_metaclass_with_multiple_bases_and_callback(self):
        # Test Path 2: formfield_callback comes from a later base class
        class BaseFormA(BaseModelForm):
            class Meta:
                formfield_callback = lambda f, **kwargs: f.formfield(**kwargs)

        class BaseFormB(BaseModelForm):
            class Meta:
                formfield_callback = lambda f, **kwargs: f.formfield(**kwargs)

        class TestModelForm(BaseFormA, BaseFormB):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

        # Verify that the callback from the last base class takes precedence
        self.assertEqual(TestModelForm._meta.formfield_callback, BaseFormB.Meta.formfield_callback)

    def test_model_form_metaclass_without_formfield_callback_in_bases(self):
        # Test Path 3: No base class has formfield_callback, so default to None
        class BaseFormA(BaseModelForm):
            class Meta:
                pass

        class BaseFormB(BaseModelForm):
            class Meta:
                pass

        class TestModelForm(BaseFormA, BaseFormB):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

        # Verify that formfield_callback is None when no base provides it
        self.assertIsNone(TestModelForm._meta.formfield_callback)

    def test_model_form_metaclass_with_explicit_formfield_callback(self):
