        class TestModelForm(BaseModelForm):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

            formfield_callback = test_callback

        # Verify that the explicit callback in attrs overrides base classes
        self.assertEqual(TestModelForm._meta.formfield_callback, test_callback)

    def test_model_form_metaclass_with_no_bases_and_no_callback(self):
        # Test Path 5: No bases and no explicit callback
        class TestModelForm(BaseModelForm):
            class Meta:
                model = ChoiceModel
                fields = '__all__'

        # Verify that formfield_callback is None when no base provides it
        # and no explicit callback is set
        self.assertIsNone(TestModelForm._meta.formfield_callback)
