def test__wrap_method_output_tuple_output():
    """Test that _wrap_method_output correctly handles tuple outputs by wrapping only the first element."""
    pd = pytest.importorskip("pandas")

    class TestEstimator(_SetOutputMixin):
        def __init__(self):
            self._sklearn_output_config = {}
            self._sklearn_auto_wrap_output_keys = {"transform"}

        def fit(self, X, y=None):
            self.n_features_in_ = X.shape[1]
            return self

        def transform(self, X, y=None):
            return (X, X * 2)  # Return a tuple of arrays

        def get_feature_names_out(self, input_features=None):
            return np.asarray([f"X{i}" for i in range(self.n_features_in_)], dtype=object)

    # Test with pandas output
    X = np.asarray([[1, 0, 3], [0, 0, 1]])
    est = TestEstimator().fit(X)
    est.set_output(transform="pandas")

    result = est.transform(X)
    assert isinstance(result[0], pd.DataFrame)
    assert isinstance(result[1], np.ndarray)
    assert_array_equal(result[0].values, X)
    assert_array_equal(result[1], X * 2)

    # Test with default output (no wrapping)
    est.set_output(transform="default")
    result = est.transform(X)
    assert isinstance(result[0], np.ndarray)
    assert_array_equal(result[0], X)
    assert isinstance(result[1], np.ndarray)
    assert_array_equal(result[1], X * 2)


