def test_diff_mapping_repr_paths():
    # Mock data for testing
    class MockVariable:
        def __init__(self, value, attrs=None):
            self.value = value
            self.attrs = attrs or {}

        def __array_function__(self, *args, **kwargs):
            return NotImplemented

        @property
        def shape(self):
            return self.value.shape

        @property
        def dtype(self):
            return self.value.dtype

        @property
        def ndim(self):
            return self.value.ndim

        def equals(self, other):
            return np.array_equal(self.value, other.value)

        def identical(self, other):
            return np.array_equal(self.value, other.value) and self.attrs == other.attrs

        def __repr__(self):
            return f"MockVariable({self.value})"

    # Create test mappings
    a_mapping = {
        "var1": MockVariable(np.array([1, 2, 3]), {"units": "m", "desc": "test"}),
        "var2": MockVariable(np.array([4, 5, 6]), {"units": "kg"}),
    }
    b_mapping = {
        "var1": MockVariable(np.array([1, 2, 4]), {"units": "m", "desc": "test"}),
        "var3": MockVariable(np.array([7, 8, 9]), {"units": "g"}),
    }

    # Test path 1: compat is string, not callable, not identical, has attrs
    actual = formatting._diff_mapping_repr(
        a_mapping, b_mapping, "identical", title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" in actual
    assert "var1" in actual
    assert "Differing attributes:" in actual
    assert "desc: test" in actual

    # Test path 2: compat is string, not callable, identical, has attrs
    a_mapping_identical = {
        "var1": MockVariable(np.array([1, 2, 3]), {"units": "m", "desc": "test"}),
        "var2": MockVariable(np.array([4, 5, 6]), {"units": "kg"}),
    }
    b_mapping_identical = {
        "var1": MockVariable(np.array([1, 2, 3]), {"units": "m", "desc": "test"}),
        "var2": MockVariable(np.array([4, 5, 6]), {"units": "kg"}),
    }
    actual = formatting._diff_mapping_repr(
        a_mapping_identical, b_mapping_identical, "identical", title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" not in actual
    assert "Attributes only on the left object:" not in actual

    # Test path 3: compat is string, not callable, not identical, no attrs
    a_mapping_no_attrs = {
        "var1": MockVariable(np.array([1, 2, 3])),
        "var2": MockVariable(np.array([4, 5, 6])),
    }
    b_mapping_no_attrs = {
        "var1": MockVariable(np.array([1, 2, 4])),
        "var2": MockVariable(np.array([4, 5, 7])),
    }
    actual = formatting._diff_mapping_repr(
        a_mapping_no_attrs, b_mapping_no_attrs, "equals", title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" in actual
    assert "Differing values:" in actual

    # Test path 4: compat is callable, not compatible
    def custom_compatible(a, b):
        return np.array_equal(a.value, b.value)

    actual = formatting._diff_mapping_repr(
        a_mapping, b_mapping, custom_compatible, title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" in actual

    # Test path 5: compat is string, not callable, compatible
    a_mapping_compatible = {
        "var1": MockVariable(np.array([1, 2, 3])),
        "var2": MockVariable(np.array([4, 5, 6])),
    }
    b_mapping_compatible = {
        "var1": MockVariable(np.array([1, 2, 3])),
        "var2": MockVariable(np.array([4, 5, 6])),
    }
    actual = formatting._diff_mapping_repr(
        a_mapping_compatible, b_mapping_compatible, "equals", title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" not in actual

    # Test path 6: compat is string, not callable, not compatible, single item
    a_mapping_single = {"var1": MockVariable(np.array([1, 2, 3]))}
    b_mapping_single = {"var1": MockVariable(np.array([1, 2, 4]))}
    actual = formatting._diff_mapping_repr(
        a_mapping_single, b_mapping_single, "equals", title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" in actual

    # Test path 7: compat is callable, not compatible, has attrs
    actual = formatting._diff_mapping_repr(
        a_mapping, b_mapping, custom_compatible, title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" in actual
    assert "Differing attributes:" in actual

    # Test path 8: compat is callable, compatible
    actual = formatting._diff_mapping_repr(
        a_mapping_compatible, b_mapping_compatible, custom_compatible, title="Variables", summarizer=formatting.summarize_datavar
    )
    assert "Differing variables:" not in actual

    # Test path 9: compat is string, not callable, not identical, no attrs
    actual = formatting._diff_mapping_repr(
        a_mapping_no_attrs, b_mapping_no_attrs, "identical", title="Variables", summarizer=formatting.summarize_datavar
    )
