class IsSubclassCheckTests(CheckTestCase):
    def test_issubclass_valid_class(self):
        class Parent:
            pass

        class Child(Parent):
            pass

        self.assertTrue(_issubclass(Child, Parent))

    def test_issubclass_not_class(self):
        # Test that non-class types don't raise TypeError
        result = _issubclass(123, int)
        self.assertFalse(result)

    def test_issubclass_non_class_with_non_class_info(self):
        # Test that neither cls nor classinfo are classes
        result = _issubclass("string", "another_string")
        self.assertFalse(result)

    def test_issubclass_class_with_non_class_info(self):
        # Test that cls is a class but classinfo isn't
        class MyClass:
            pass

        result = _issubclass(MyClass, "not_a_class")
        self.assertFalse(result)

    def test_issubclass_non_class_with_class_info(self):
        # Test that cls isn't a class but classinfo is
        class Parent:
            pass

        result = _issubclass(42, Parent)
        self.assertFalse(result)
