class DeferredAttributeTests(SimpleTestCase):
    def test_deferred_attribute_get_none_instance(self):
        # Path 1: instance is None
        class FakeField:
            attname = 'fake_field'

        attr = DeferredAttribute(FakeField())
        result = attr.__get__(None, None)
        self.assertIs(result, attr)

    def test_deferred_attribute_get_field_not_in_dict_and_refresh_from_db(self):
        # Path 2: field_name not in data, val is None, so refresh_from_db is called
        class MockInstance:
            def __init__(self):
                self.__dict__ = {}
                self._meta = type('Meta', (), {'object_name': 'TestModel'})

            def refresh_from_db(self, fields):
                # Simulate setting the field value
                self.__dict__['fake_field'] = 'test_value'

        class FakeField:
            attname = 'fake_field'
            model = MockInstance

        instance = MockInstance()
        attr = DeferredAttribute(FakeField())

        # Ensure field is not in __dict__ initially
        self.assertNotIn('fake_field', instance.__dict__)
        result = attr.__get__(instance, type(instance))
        self.assertEqual(result, 'test_value')
        self.assertIn('fake_field', instance.__dict__)

    def test_deferred_attribute_get_field_not_in_dict_and_check_parent_chain_returns_value(self):
        # Path 3: field_name not in data, val is not None, so data[field_name] = val
        class MockInstance:
            def __init__(self):
                self.__dict__ = {}
                self._meta = type('Meta', (), {'object_name': 'TestModel'})

            @property
            def parent_field(self):
                return 'parent_value'

        class FakeField:
            attname = 'fake_field'
            model = MockInstance
            primary_key = True

        instance = MockInstance()
        attr = DeferredAttribute(FakeField())

        # Mock _check_parent_chain to return a value
        with patch.object(DeferredAttribute, '_check_parent_chain') as mock_check:
            mock_check.return_value = 'parent_value'
            result = attr.__get__(instance, type(instance))
            self.assertEqual(result, 'parent_value')
            self.assertIn('fake_field', instance.__dict__)
            self.assertEqual(instance.__dict__['fake_field'], 'parent_value')

    def test_deferred_attribute_get_field_in_dict(self):
        # Path 4: field_name in data, directly return from __dict__
        class MockInstance:
            def __init__(self):
                self.__dict__ = {'fake_field': 'cached_value'}
                self._meta = type('Meta', (), {'object_name': 'TestModel'})

        class FakeField:
            attname = 'fake_field'

        instance = MockInstance()
        attr = DeferredAttribute(FakeField())
        result = attr.__get__(instance, type(instance))
        self.assertEqual(result, 'cached_value')
