def test_remove_blacklisted_style_params():
    # Test Path 1: Multiple blacklisted keys with warn=True
    d = {'interactive': 'True', 'backend': 'agg'}
    with pytest.warns(mpl._api.MatplotlibDeprecationWarning) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=True)
    assert result == {}
    assert len(warning_records) == 2
    assert 'interactive' in warning_records[0].message.args[0]
    assert 'backend' in warning_records[1].message.args[0]

    # Test Path 2: Multiple blacklisted keys, one with warn=False
    d = {'interactive': 'True', 'backend': 'agg'}
    with warnings.catch_warnings(record=True) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=False)
    assert result == {}
    assert len(warning_records) == 0

    # Test Path 3: Mix of blacklisted and non-blacklisted keys, warn=True
    d = {'interactive': 'True', 'axes.facecolor': 'red'}
    with pytest.warns(mpl._api.MatplotlibDeprecationWarning) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=True)
    assert result == {'axes.facecolor': 'red'}
    assert len(warning_records) == 1
    assert 'interactive' in warning_records[0].message.args[0]

    # Test Path 4: Only blacklisted keys, warn=True
    d = {'interactive': 'True', 'backend': 'agg'}
    with pytest.warns(mpl._api.MatplotlibDeprecationWarning) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=True)
    assert result == {}
    assert len(warning_records) == 2

    # Test Path 5: Multiple blacklisted keys, first with warn=False, second with warn=True
    d = {'interactive': 'True', 'backend': 'agg'}
    with pytest.warns(mpl._api.MatplotlibDeprecationWarning) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=True)
    assert result == {}
    assert len(warning_records) == 2

    # Test Path 6: Multiple blacklisted keys, both with warn=False
    d = {'interactive': 'True', 'backend': 'agg'}
    with warnings.catch_warnings(record=True) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=False)
    assert result == {}
    assert len(warning_records) == 0

    # Test Path 7: Mix of blacklisted and non-blacklisted keys, warn=False
    d = {'interactive': 'True', 'axes.facecolor': 'red'}
    with warnings.catch_warnings(record=True) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=False)
    assert result == {'axes.facecolor': 'red'}
    assert len(warning_records) == 0

    # Test Path 8: Only blacklisted keys, warn=False
    d = {'interactive': 'True', 'backend': 'agg'}
    with warnings.catch_warnings(record=True) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=False)
    assert result == {}
    assert len(warning_records) == 0

    # Test Path 9: First non-blacklisted, then blacklisted, warn=True
    d = {'axes.facecolor': 'blue', 'interactive': 'True'}
    with pytest.warns(mpl._api.MatplotlibDeprecationWarning) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=True)
    assert result == {'axes.facecolor': 'blue'}
    assert len(warning_records) == 1
    assert 'interactive' in warning_records[0].message.args[0]

    # Test Path 10: First non-blacklisted, then blacklisted, warn=False
    d = {'axes.facecolor': 'blue', 'interactive': 'True'}
    with warnings.catch_warnings(record=True) as warning_records:
        result = style._remove_blacklisted_style_params(d, warn=False)
    assert result == {'axes.facecolor': 'blue'}
    assert len(warning_records) == 0
