def test_item_location_with_py_path_local_fspath(testdir):
    """Test that Item.location returns correct path when fspath is a py.path.local object."""
    p = testdir.makepyfile(
        """
        import pytest

        class CustomItem(pytest.Item):
            def __init__(self, name, parent):
                super().__init__(name, parent)
                self.fspath = py.path.local(__file__)

            def reportinfo(self):
                return self.fspath, 10, "test"

        def test_function():
            pass
    """
    )
    items = testdir.getitems(p.strpath)
    item = items[0]

    # Mock session to ensure _node_location_to_relpath is called
    class MockSession:
        def _node_location_to_relpath(self, fspath):
            return fspath.relto(py.path.local.cwd())

    item.session = MockSession()

    # Ensure reportinfo returns py.path.local
    assert isinstance(item.reportinfo()[0], py.path.local)

    result = item.location
    assert isinstance(result[0], py.path.local)
    assert result[1] == 10
    assert result[2] == "test"


